/* Fictional presentation records refresh once per Arizona date; existing visits are kept. */
function seedPresentationDay(){
 if(extras.presentationDay===today)return;
 for(const barber of barbers)extras.chairTerms[barber.id]??={mode:'split',barberPercent:60,amount:0,period:'week',collectionDay:1};
 const fixtures=[['John B.','alex','9:00 AM','cut','completed'],['Alex Morgan','alex','10:00 AM','cut','in_service'],['Ryan Smith','alex','11:15 AM','combo','confirmed'],['Marcus Reed','alex','2:00 PM','beard','confirmed'],['Daniel Lee','alex','3:15 PM','cut','confirmed'],['Chris Parker','jordan','10:30 AM','combo','confirmed'],['Sam Taylor','jordan','1:15 PM','cut','confirmed'],['Jordan Ellis','watkins','3:00 PM',null,'confirmed']];
 for(const [client,barber,time,service,status] of fixtures){const s=servicesFor(barber).find(x=>x.id===service)||servicesFor(barber).find(x=>x.active!==false);if(!s)continue;const id=`presentation-${today}-${barber}-${client.replaceAll(' ','-')}`;if(bookings.some(b=>b.id===id||b.barber===barber&&b.date===today&&b.status!=='cancelled'&&overlaps(time,s.min,b.time,bookingDuration(b)))||extras.blocks.some(b=>b.barber===barber&&b.date===today&&clockMinutes(b.start)<minutes(time)+s.min&&clockMinutes(b.end)>minutes(time)))continue;
 const item={...s,...(status==='completed'?{price:32}:{})},b={id,client,barber,service:item.id,services:[item.id],bookedServices:[item],durationMin:item.min,estimateCents:Math.round(item.price*100),date:today,time,location:'scottsdale',status,policy:structuredClone(extras.bookingPolicy),presentationExample:true};
 if(status==='completed'){b.ticket=HFTickets.create(id,item);HFTickets.finalize(b.ticket);HFTickets.send(b.ticket);HFTickets.approve(b.ticket,b.ticket.revision,2000);b.settlement={status:'paid',method:'cash',amountCents:5200,at:Date.now(),source:'example'};}
 if(status==='in_service'){b.ticket=HFTickets.create(id,item);checked[id]=true;}bookings.push(b);
 }
 const clients=[['Alex Morgan',['Hey Lara, same length on top as last time?','And a low taper please.','See you shortly!']],['Ryan Smith',['Can we do the beard trim too?']],['Marcus Reed',['First time here. Is there parking by the shop?']]];
 clients.forEach(([client,texts],i)=>{const t=threadFor(client,'alex');if(t.messages.some(m=>m.id===`presentation-chat-${today}-${i}-0`))return;texts.forEach((body,j)=>t.messages.push({id:`presentation-chat-${today}-${i}-${j}`,role:'Customer',name:client,body,at:Date.now()-(8-i*2-j)*60000,readBy:['Customer'],delivered:true}));});
 const shop=threadFor('John B.',null,'general');if(!shop.messages.some(m=>m.id===`presentation-shop-${today}`))shop.messages.push({id:`presentation-shop-${today}`,role:'Customer',name:'John B.',body:'Thanks for the cut today! Where can I leave a review?',at:Date.now()-30000,readBy:['Customer'],delivered:true});
 extras.presentationDay=today;save();
}
const reviewBrandIcons={google:`<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.2c0-.7-.1-1.4-.2-2H12v3.9h5.4a4.6 4.6 0 0 1-2 3v2.5h3.2c1.9-1.7 3-4.3 3-7.4Z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.6-2.4l-3.2-2.5c-.9.6-2 .9-3.4.9-2.6 0-4.8-1.7-5.6-4.1H3v2.6A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.4 13.9A6 6 0 0 1 6.1 12c0-.7.1-1.3.3-1.9V7.5H3A10 10 0 0 0 2 12c0 1.6.4 3.1 1 4.5l3.4-2.6Z"/><path fill="#EA4335" d="M12 6c1.5 0 2.8.5 3.8 1.5l2.9-2.9A9.6 9.6 0 0 0 12 2a10 10 0 0 0-9 5.5l3.4 2.6A6 6 0 0 1 12 6Z"/></svg>`,yelp:`<svg viewBox="0 0 24 24" aria-hidden="true" fill="#ff1a1a"><path d="m10 2 1 8-3 1-4-6Zm5 8 6-3 1 5-6 1Zm1 5 5 3-4 4-3-6Zm-5 1 1 7-6-2 3-5Zm-4-4 1 3-6 3-1-6Z"/></svg>`,facebook:`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#1877F2"/><path fill="white" d="M13.5 22v-8h2.7l.4-3h-3.1V9c0-.9.3-1.5 1.5-1.5h1.7V4.8c-.3 0-1.3-.1-2.4-.1-2.4 0-4.1 1.5-4.1 4.2V11H7.5v3h2.7v8Z"/></svg>`};
function publicReviewPanel(location=extras.location){const university=location==='university',place=university?'ChIJgfu_iskJK4cRxSu5U-2xUYg':'ChIJwcRaf-gLK4cRz_x9htxOvTM',yelp='https://www.yelp.com/search?'+new URLSearchParams({find_desc:'Hairflix Barbershop',find_loc:university?'Tempe, AZ':'Scottsdale, AZ'});return `<section class="panel public-review-panel"><h2>Share your experience.</h2><p class="muted">Your honest review helps others find the shop.</p><div class="review-platforms"><a href="https://search.google.com/local/writereview?placeid=${place}" target="_blank" rel="noopener noreferrer">${reviewBrandIcons.google}<span>Review on Google</span>${icon('arrow')}</a><a href="${esc(yelp)}" target="_blank" rel="noopener noreferrer">${reviewBrandIcons.yelp}<span>Find us on Yelp</span>${icon('arrow')}</a><a href="https://facebook.com/Hairflix-Barbershop-100067809754591" target="_blank" rel="noopener noreferrer">${reviewBrandIcons.facebook}<span>Visit us on Facebook</span>${icon('arrow')}</a></div></section><section class="panel instagram-gift"><span class="instagram-gift-icon">${icon('gift')}</span><h2>Your cut deserves a story.</h2><p>Tag <strong>@hairflix_barbershop</strong> in your Instagram story and show your barber to claim a <strong>free gift or eyebrow service.</strong></p><a class="btn secondary full" href="https://instagram.com/hairflix_barbershop/" target="_blank" rel="noopener noreferrer">Tag us on Instagram ${icon('arrow')}</a><small>This offer is for your story. No review is required.</small></section>`;}
feedbackThanks=function(){const review=extras.reviews.find(r=>r.visit===state.feedbackVisit);return `<div class="narrow">${head('Thanks for your feedback.','Your private feedback is visible to management only.')}${publicReviewPanel(review?.location||extras.location)}${linkPage('Back to home','home','Customer','secondary full')}</div>`;};
const reviewBeforePresentation=reviewPage;reviewPage=function(){return reviewBeforePresentation()+(bookings.some(b=>b.client==='John B.'&&b.ticket?.approval)?publicReviewPanel(bookings.find(b=>b.id===state.visitId)?.location||extras.location):'');};
const receiptBeforePresentation=receiptPage;receiptPage=function(){return receiptBeforePresentation()+(state.role==='Customer'?publicReviewPanel(visitFor()?.location||extras.location):'');};
seedPresentationDay();render();
